 44  /**
 45   * A repeatable list of short strings, used for actions and risks alike.
 46   *
 47   * The two report fields that are lists are lists of sentences a person wrote,
 48   * not of anything the run recorded, so they get a plain editor rather than
 49   * anything that pretends to be evidence.
 50   */
 51  function StringList({
 52    label,
 53    placeholder,
 54    addLabel,
 55    removeLabel,
 56    values,
 57    onChange,
 58    disabled,
 59  }: {
 60    label: string;
 61    placeholder: string;
 62    addLabel: string;
 63    removeLabel: string;
 64    values: string[];
 65    onChange: (next: string[]) => void;
 66    disabled: boolean;
 67  }) {
 68    const [draft, setDraft] = useState("");
 69  
 70    function add() {
 71      const text = draft.trim();
 72      if (!text) return;
 73      onChange([...values, text]);
 74      setDraft("");
 75    }
 76  
 77    return (
 78      <div className="string-list">
 79        <label>
 80          {label}
 81          <input
 82            value={draft}
 83            onChange={(event) => setDraft(event.target.value)}
 84            placeholder={placeholder}
 85            maxLength={500}
 86            disabled={disabled}
 87          />
 88        </label>
 89        <button
 90          type="button"
 91          className="button button-ghost"
 92          onClick={add}
 93          disabled={disabled || !draft.trim()}
 94        >
 95          {addLabel}
 96        </button>
 97        {values.length > 0 && (
 98          <ul className="string-list-items">
 99            {values.map((value, index) => (
100              <li key={`${index}-${value}`}>
101                <span>{value}</span>
102                <button
103                  type="button"
104                  className="button button-ghost"
105                  onClick={() => onChange(values.filter((_, position) => position !== index))}
106                  disabled={disabled}
107                >
108                  {removeLabel}
109                </button>
110              </li>
111            ))}
112          </ul>
113        )}
114      </div>
115    );
116  }
